import java.util.Arrays;

public class GradeAnalyticsEngine {
    public static double calculateAverage(int[] scores) {
        if (scores == null || scores.length == 0) return 0.0;
        int total = 0;
        for (int s : scores) total += s;
        return (double) total / scores.length;
    }

    public static int findMaxIndex(int[] scores) {
        if (scores == null || scores.length == 0) return -1;
        int maxIdx = 0;
        for (int i = 1; i < scores.length; i++) {
            if (scores[i] > scores[maxIdx]) {
                maxIdx = i;
            }
        }
        return maxIdx;
    }

    public static int countHonors(int[] scores, int threshold) {
        int count = 0;
        for (int s : scores) {
            if (s >= threshold) count++;
        }
        return count;
    }

    public static int[] getSortedLeaderboard(int[] scores) {
        int[] copy = Arrays.copyOf(scores, scores.length);
        Arrays.sort(copy);
        return copy;
    }

    public static void main(String[] args) {
        int[] studentMarks = {78, 92, 45, 88, 64, 95, 52};

        System.out.printf("Class Average: %.2f%n", calculateAverage(studentMarks));
        int topIdx = findMaxIndex(studentMarks);
        System.out.println("Top Score: " + studentMarks[topIdx] + " (Student #" + topIdx + ")");
        System.out.println("Honors Count (>=85): " + countHonors(studentMarks, 85));

        int[] leaderboard = getSortedLeaderboard(studentMarks);
        System.out.println("Sorted Leaderboard: " + Arrays.toString(leaderboard));
        System.out.println("Original Array Intact: " + Arrays.toString(studentMarks));
    }
}

