    public static boolean hasScore(int[] scores, int target) {
        for (int s : scores) {
            if (s == target) return true;
        }
        return false;
    }

    public static void main(String[] args) {
        int[] marks = {75, 82, 90, 68};
        System.out.println("Has 90: " + hasScore(marks, 90) + " | Has 100: " + hasScore(marks, 100));
    }
}

