public class Main {
    public static void printCohortSummary(int[] scores) {
        int sum = 0;
        int min = scores[0];
        int max = scores[0];
        for (int s : scores) {
            sum += s;
            if (s < min) min = s;
            if (s > max) max = s;
        }
        double avg = (double) sum / scores.length;
        System.out.println("Total Students: " + scores.length);
        System.out.println("Average: " + avg);
        System.out.println("Min Score: " + min);
        System.out.println("Max Score: " + max);
    }

    public static void main(String[] args) {
        int[] marks = {70, 85, 95, 60};
        printCohortSummary(marks);
    }
}
